async fn refused_link_leaves_a_funded_trade_to_release_through_the_custodial_lock_path(
    pool: PgPool,
) {
    common::seed_zar_fx_rate(&pool).await;
    let seller = seed_user(&pool, "seller").await;
    let buyer = seed_user(&pool, "buyer").await;
    seed_wallet(&pool, seller, "USDT", SELLER_START).await;
    let offer = insert_usdt_offer(&pool, seller, OfferType::Sell, EscrowType::Custodial).await;
    let buyer_token = token_for(&pool, buyer).await;
    let seller_token = token_for(&pool, seller).await;
    let (status, trade) = call(
        &pool,
        "POST",
        "/api/v1/trades",
        &buyer_token,
        &trade_body(offer, None),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{trade}");
    let trade_id = trade_id_of(&trade);

    let (link_status, link) = call(
        &pool,
        "POST",
        &format!("/api/v1/escrow/{trade_id}/link"),
        &buyer_token,
        &json!({
            "contractAddress": "TXyz910contractaddress",
            "network": "tron_mainnet",
            "txHash": "0xabc910",
        }),
    )
    .await;
    assert_eq!(link_status, StatusCode::UNPROCESSABLE_ENTITY, "{link}");
    assert_eq!(link["code"], "unsupported_escrow_type", "{link}");

    let (paid_status, paid) = call(
        &pool,
        "POST",
        &format!("/api/v1/trades/{trade_id}/mark-paid"),
        &buyer_token,
        &json!({}),
    )
    .await;
    assert_eq!(paid_status, StatusCode::OK, "{paid}");
    let (done_status, done) = call(
        &pool,
        "POST",
        &format!("/api/v1/trades/{trade_id}/complete"),
        &seller_token,
        &json!({}),
    )
    .await;
    assert_eq!(done_status, StatusCode::OK, "{done}");

    let escrow = escrow_snapshot(&pool, trade_id).await;
    assert_eq!(escrow.0, "custodial");
    assert_eq!(escrow.1, "released");
    assert_eq!(escrow.2, None);
    assert_eq!(escrow.3, None);
    assert_eq!(escrow.4, None);
    let lock_released: bool = sqlx::query_scalar(
        "SELECT released_at IS NOT NULL FROM wallet_locks WHERE trade_id = $1",
    )
    .bind(trade_id)
    .fetch_one(&pool)
    .await
    .expect("lock row");
    assert!(lock_released);
    assert_eq!(balances(&pool, seller, "USDT").await.1, 0);
    let stored: String = sqlx::query_scalar("SELECT status::text FROM trades WHERE id = $1")
        .bind(trade_id)
        .fetch_one(&pool)
        .await
        .expect("trade status");
    assert_eq!(stored, "completed");
}
